#!/usr/bin/env node
// Generates contracts/yul/gen/*.yul from contracts/yul/*.yul.tmpl, splicing in the shared WOTS+C core.
// Run `node tools/gen-yul.mjs --check` in CI to make sure the generated files are up to date.
import { readFileSync, writeFileSync } from "node:fs";

const root = new URL("../contracts/", import.meta.url);
const MAX_STEP = 15; // must match packages/pq/src/params.ts

// wots_walk(d): applies chain steps d..14 to the value at memory 0x20, with the chain tweak at 0x00.
// Unrolled into straight-line code behind a 4-level binary decision tree on d (no per-step loop overhead).
function walkTree(lo, hi, indent) {
  const pad = " ".repeat(indent);
  if (hi - lo === 1) {
    const steps = [];
    for (let j = lo; j < MAX_STEP; j++) steps.push(`${pad}mstore8(0x1d, ${j}) mstore(0x20, keccak256(0x00, 0x40))`);
    return steps.length ? steps.join("\n") : `${pad}// d = ${lo}: already at the public end`;
  }
  const mid = (lo + hi) >> 1;
  return [
    `${pad}switch lt(d, ${mid})`,
    `${pad}case 0 {`,
    walkTree(mid, hi, indent + 4),
    `${pad}}`,
    `${pad}default {`,
    walkTree(lo, mid, indent + 4),
    `${pad}}`,
  ].join("\n");
}
const walk = [
  "            // GENERATED by tools/gen-yul.mjs: applies chain steps d..14 (byte 29 of the tweak = step index).",
  "            function wots_walk(d) {",
  walkTree(0, 16, 16),
  "            }",
].join("\n");

const core = readFileSync(new URL("yul/wots_core.yul", root), "utf8").trimEnd().replace("// @@WOTS_WALK@@", walk);
const check = process.argv.includes("--check");
let stale = false;

for (const name of ["LifeboatAccount", "WotsHarness"]) {
  const tmpl = readFileSync(new URL(`yul/${name}.yul.tmpl`, root), "utf8");
  if (!tmpl.includes("// @@WOTS_CORE@@")) throw new Error(`${name}: missing core placeholder`);
  const out = tmpl.replace("// @@WOTS_CORE@@", core);
  const target = new URL(`yul/gen/${name}.yul`, root);
  let current = "";
  try {
    current = readFileSync(target, "utf8");
  } catch {}
  if (current === out) continue;
  if (check) {
    console.error(`stale: contracts/yul/gen/${name}.yul`);
    stale = true;
  } else {
    writeFileSync(target, out);
    console.log(`wrote contracts/yul/gen/${name}.yul`);
  }
}
if (stale) process.exit(1);
